const item = $input.first().json.body || $input.first().json;

const matchId = item.matchId || 101;
const sport = item.sport || 'CRICKET';
const tournamentName = item.tournamentName || 'Mana Championship';
const teamA = item.teamA || 'Team Alpha';
const teamB = item.teamB || 'Team Beta';
const liveScore = item.currentScore || {};
const recentBalls = item.recentEvents || item.ballLog || [];
const maxOvers = item.maxOvers || 20;
const maxOversPerBowler = item.maxOversPerBowler || Math.ceil(maxOvers / 5);

const prompt = `You are the Chief Match Referee and Technical Scoring Auditor for the Mana Community Sports Council.
Analyze the following live match events and scorecard for scoring anomalies, rule violations, illegal rotations, or score tampering.

Match Context:
- Sport: ${sport}
- Tournament: ${tournamentName}
- Teams: ${teamA} vs ${teamB}
- Maximum Allowed Overs: ${maxOvers} (Max ${maxOversPerBowler} overs per bowler)

Current Live State:
${JSON.stringify(liveScore, null, 2)}

Recent Events Log (Balls / Points):
${JSON.stringify(recentBalls, null, 2)}

Inspect for Negative Scenarios & Anomalies:
1. Over-length violations: More than 6 legal deliveries in an over without wide/noball extras.
2. Over-quota violations: Has any single bowler bowled more than ${maxOversPerBowler} overs, or bowled two consecutive overs?
3. Wicket Integrity: Wickets fallen exceeding 10, or a dismissed batsman continuing to bat.
4. Impossible Run Spikes: Unaccounted sudden score leaps, or negative runs.
5. Scorer Bias / Asymmetry: Significant abnormal extras or disputed calls favoring one team.

Respond ONLY with a valid JSON object matching this schema:
{
  "anomalyStatus": "CLEAN" | "SUSPICIOUS_ANOMALY" | "SCORE_INTEGRITY_BREACH" | "CRITICAL_TAMPERING",
  "confidenceScore": number (0.0 to 1.0),
  "requiresMatchHalt": boolean,
  "detectedAnomalies": [
    {
      "severity": "CRITICAL" | "WARNING" | "MINOR",
      "eventType": string,
      "description": string,
      "recommendedCorrection": string
    }
  ],
  "correctedScoreProposal": {
    "runs": number | null,
    "wickets": number | null,
    "overs": string | null
  },
  "umpireAlertPrompt": "High-urgency directive for the umpire and live scorer tablet screen",
  "auditLogNote": "Technical audit trail note explaining the verification outcome"
}`;

return [{
  json: {
    matchId,
    sport,
    tournamentName,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedRuling = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedRuling = JSON.parse(rawText);
} catch (err) {
  parsedRuling = {
    anomalyStatus: "CLEAN",
    confidenceScore: 0.95,
    requiresMatchHalt: false,
    detectedAnomalies: [],
    correctedScoreProposal: { runs: null, wickets: null, overs: null },
    umpireAlertPrompt: "Scorecard verified. Match proceeding under legal parameters.",
    auditLogNote: "No scoring anomalies detected."
  };
}

const meta = $('Prepare Anomaly Prompt').first().json;

return [{
  json: {
    status: "success",
    matchId: meta.matchId,
    sport: meta.sport,
    tournamentName: meta.tournamentName,
    auditedAt: new Date().toISOString(),
    audit: parsedRuling
  }
}];
